  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 The Progressive Movement and Its Reforms$j$, $j${"readings": [{"title": "Micah 6 (King James Version)", "url": "/portal/bible/Micah/6"}], "body": "From about 1890 to 1920 the Progressive Movement worked to fix the problems of the Gilded Age. Progressives believed government could protect citizens and improve society.\n\nMuckrakers were writers who exposed wrongs. Upton Sinclair's novel The Jungle (1906) described filthy meatpacking plants, and Ida Tarbell exposed Standard Oil. Congress responded with the Meat Inspection Act and the Pure Food and Drug Act in 1906.\n\nThree presidents led reform. Theodore Roosevelt used the Square Deal, broke up trusts and protected national forests and parks. William Howard Taft continued trust busting. Woodrow Wilson passed the Federal Reserve Act of 1913 and the Clayton Antitrust Act.\n\nFour amendments came in this era. The Sixteenth Amendment allowed a federal income tax. The Seventeenth Amendment provided for direct election of senators. The Eighteenth Amendment prohibited alcohol. The Nineteenth Amendment gave women the right to vote. States also adopted the initiative, referendum and recall.\n\nMicah 6:8 says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nYour task: (1) Define muckraker and give one example. (2) Name two laws that came from muckraking. (3) Match each of the 16th to 19th Amendments to its purpose.\n\nFlorida standards: SS.912.A.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.3", "script": "Welcome to Unit 3. Listen, from about eighteen ninety to nineteen twenty the Progressive Movement worked to fix the problems of the Gilded Age. Progressives believed government could protect citizens and improve society.\n\nNow watch this. Muckrakers were writers who exposed wrongs. Upton Sinclair's novel The Jungle, in nineteen oh six, described filthy meatpacking plants, and Ida Tarbell exposed Standard Oil. Congress responded with the Meat Inspection Act and the Pure Food and Drug Act in nineteen oh six.\n\nLook at this. Three presidents led reform. Theodore Roosevelt used the Square Deal, broke up trusts and protected national forests and parks. William Howard Taft continued trust busting. Woodrow Wilson passed the Federal Reserve Act of nineteen thirteen and the Clayton Antitrust Act.\n\nFour amendments came in this era. The Sixteenth allowed a federal income tax. The Seventeenth provided for direct election of senators. The Eighteenth prohibited alcohol. The Nineteenth gave women the right to vote.\n\nMicah six and eight says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nYour task today. Define muckraker and give one example. Name two laws that came from muckraking. And match each of the sixteenth to nineteenth amendments to its purpose. Take the four question check.\n\nDo justly, love mercy, walk humbly. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 The Progressive Movement and Its Reforms$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Women's Suffrage, Civil Rights Leaders and the NAACP$j$, $j${"readings": [{"title": "Galatians 3 (King James Version)", "url": "/portal/bible/Galatians/3"}], "body": "The Progressive Era also brought a long struggle for equal rights. Women had worked for the vote since the Seneca Falls Convention of 1848, where Elizabeth Cady Stanton and Lucretia Mott led. Susan B. Anthony, Carrie Chapman Catt and Alice Paul carried the cause forward with marches, petitions and pickets. In 1920 the Nineteenth Amendment was ratified, giving women the right to vote.\n\nAfrican Americans faced segregation and violence. Booker T. Washington, founder of Tuskegee Institute, urged education and economic skills first, in his Atlanta Compromise speech of 1895. W. E. B. Du Bois, in The Souls of Black Folk, demanded full civil rights and higher education for the Talented Tenth. Ida B. Wells fought lynching with her reporting. In 1909 Du Bois, Wells and others helped found the National Association for the Advancement of Colored People, the NAACP, which used courts and public pressure.\n\nThe Supreme Court's Plessy v. Ferguson decision in 1896 allowed separate but equal facilities. Reformers kept working to overturn it, which came in 1954.\n\nGalatians 3:28 says, There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus.\n\nYour task: (1) Name three leaders of the suffrage movement. (2) Contrast Washington and Du Bois. (3) Explain what the NAACP did.\n\nFlorida standards: SS.912.A.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.3", "script": "Welcome back. Listen, the Progressive Era also brought a long struggle for equal rights. Women had worked for the vote since the Seneca Falls Convention of eighteen forty eight, where Elizabeth Cady Stanton and Lucretia Mott led. Susan B. Anthony, Carrie Chapman Catt and Alice Paul carried the cause forward with marches, petitions and pickets. In nineteen twenty the Nineteenth Amendment gave women the right to vote.\n\nNow watch this. African Americans faced segregation and violence. Booker T. Washington, founder of Tuskegee Institute, urged education and economic skills first, in his Atlanta Compromise speech of eighteen ninety five. W. E. B. Du Bois demanded full civil rights and higher education for the Talented Tenth. Ida B. Wells fought lynching with her reporting. In nineteen oh nine Du Bois, Wells and others helped found the NAACP, which used courts and public pressure.\n\nLook at this. The Supreme Court's Plessy v. Ferguson decision in eighteen ninety six allowed separate but equal facilities. Reformers kept working, and that decision was overturned in nineteen fifty four.\n\nGalatians three and twenty eight says, There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus.\n\nYour task today. Name three leaders of the suffrage movement. Contrast Washington and Du Bois. And explain what the NAACP did. Take the four question check.\n\nEvery person is made in the image of God. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Women's Suffrage, Civil Rights Leaders and the NAACP$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Imperialism: The Spanish American War and America as a World Power$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "By 1890 the United States looked beyond its borders. Reasons for imperialism were trade and markets, naval power, and a belief in spreading American ideas and religion. Alfred Thayer Mahan argued for a strong navy.\n\nIn 1867 Secretary of State William Seward bought Alaska from Russia. In 1893 American planters helped overthrow Queen Liliuokalani in Hawaii, and the islands were annexed in 1898.\n\nCuba was fighting Spain for freedom. Newspapers called yellow journalism stirred American anger, and the explosion of the battleship Maine in Havana harbor in 1898 led to war. The Spanish American War was short. The Treaty of Paris gave the United States the Philippines, Guam and Puerto Rico, and Cuba became free under American influence. Filipinos who wanted independence fought a hard war that followed.\n\nTheodore Roosevelt built the Panama Canal, finished in 1914, and announced the Roosevelt Corollary to the Monroe Doctrine, claiming the right to act as police power in Latin America. The Open Door Policy asked for fair trade with China.\n\nProverbs 16:18 says, Pride goeth before destruction, and an haughty spirit before a fall.\n\nYour task: (1) Give two reasons for American imperialism. (2) Explain how the Spanish American War began and ended. (3) Tell why the Panama Canal mattered.\n\nFlorida standards: SS.912.A.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.4", "script": "Welcome back. Listen, by eighteen ninety the United States looked beyond its borders. The reasons were trade and markets, naval power, and a belief in spreading American ideas and religion. Alfred Thayer Mahan argued for a strong navy.\n\nNow watch this. In eighteen sixty seven Secretary of State William Seward bought Alaska from Russia. In eighteen ninety three American planters helped overthrow Queen Liliuokalani in Hawaii, and the islands were annexed in eighteen ninety eight.\n\nLook at this. Cuba was fighting Spain for freedom. Newspapers practicing yellow journalism stirred American anger, and the explosion of the battleship Maine in Havana harbor in eighteen ninety eight led to war. The war was short. The Treaty of Paris gave the United States the Philippines, Guam and Puerto Rico, and Cuba became free under American influence. Filipinos who wanted independence fought a hard war that followed.\n\nTheodore Roosevelt built the Panama Canal, finished in nineteen fourteen, and announced the Roosevelt Corollary, claiming the right to act as police power in Latin America. The Open Door Policy asked for fair trade with China.\n\nProverbs sixteen and eighteen says, Pride goeth before destruction, and an haughty spirit before a fall.\n\nYour task today. Give two reasons for American imperialism. Explain how the Spanish American War began and ended. And tell why the Panama Canal mattered. Take the four question check.\n\nPower requires humility. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Imperialism: The Spanish American War and America as a World Power$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 World War I and the Home Front$j$, $j${"readings": [{"title": "John 15 (King James Version)", "url": "/portal/bible/John/15"}], "body": "World War I began in Europe in 1914. Causes are remembered with the word MAIN: militarism, alliances, imperialism and nationalism. The assassination of Archduke Franz Ferdinand in Sarajevo lit the fuse. The Allies, including Britain, France and Russia, fought the Central Powers, including Germany and Austria Hungary.\n\nPresident Woodrow Wilson kept the United States neutral at first. German submarine attacks, such as the sinking of the Lusitania in 1915, and the Zimmermann Telegram, which urged Mexico to join Germany, pushed America into the war in April 1917. About two million American troops, led by General John Pershing, helped turn the tide. The war ended with the armistice on November 11, 1918.\n\nAt home the nation mobilized. The government drafted soldiers, sold Liberty Bonds and created the War Industries Board. Women worked in factories, and many African Americans moved north in the Great Migration. The Espionage and Sedition Acts limited free speech.\n\nWilson offered Fourteen Points for peace and a League of Nations, but the Senate refused to join. The Treaty of Versailles blamed Germany and laid the ground for future trouble.\n\nJohn 15:13 says, Greater love hath no man than this, that a man lay down his life for his friends.\n\nYour task: (1) Name the four causes in MAIN. (2) Give two reasons America entered the war. (3) Describe two changes on the home front.\n\nFlorida standards: SS.912.A.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.4", "script": "Welcome back. Listen, World War I began in Europe in nineteen fourteen. Remember the causes with the word MAIN: militarism, alliances, imperialism and nationalism. The assassination of Archduke Franz Ferdinand in Sarajevo lit the fuse. The Allies, including Britain, France and Russia, fought the Central Powers, including Germany and Austria Hungary.\n\nNow watch this. President Wilson kept the United States neutral at first. German submarine attacks, like the sinking of the Lusitania in nineteen fifteen, and the Zimmermann Telegram, which urged Mexico to join Germany, pushed America into the war in April nineteen seventeen. About two million American troops, led by General John Pershing, helped turn the tide. The war ended with the armistice on November eleventh, nineteen eighteen.\n\nLook at this. At home the nation mobilized. The government drafted soldiers, sold Liberty Bonds and created the War Industries Board. Women worked in factories, and many African Americans moved north in the Great Migration. The Espionage and Sedition Acts limited free speech.\n\nWilson offered Fourteen Points for peace and a League of Nations, but the Senate refused to join. The Treaty of Versailles blamed Germany and laid the ground for future trouble.\n\nJohn fifteen and thirteen says, Greater love hath no man than this, that a man lay down his life for his friends.\n\nYour task today. Name the four causes in MAIN. Give two reasons America entered the war. And describe two changes on the home front. Take the four question check.\n\nHonor those who served. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 World War I and the Home Front$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Reform, Empire and War$j$, $j${"prompt": "Write an essay answering this question: How did the United States change at home and abroad between 1890 and 1920? Use complete sentences and label each part. Micah 6:8 says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nPart 1: Explain what the Progressives wanted and give three reforms they achieved.\nPart 2: Explain how women and African Americans worked for equal rights and name three leaders.\nPart 3: Explain why the United States became an imperial power and give two results.\nPart 4: Explain why America entered World War I and how the war changed life at home.\nPart 5: Compare one success and one failure of the Progressive Era.\nPart 6: Give your thesis on whether the nation lived up to its ideals of justice in this period, using evidence and one KJV verse.", "rubric": "70 points. Progressive reforms: 12 points. Rights movements: 12 points. Imperialism: 10 points. World War I: 10 points. Success and failure: 8 points. Thesis and evidence: 14 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Reform, Empire and War$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Justice at Home and Power Abroad$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains which Progressive reform you think helped ordinary people most, (2) tells how the struggle for women's suffrage and civil rights reflects Galatians 3:28, (3) discusses whether the United States was wise to take colonies after the Spanish American War, and (4) connects your answer to Proverbs 16:18, which says, Pride goeth before destruction, and an haughty spirit before a fall. Then write a respectful reply of at least 40 words to another student, or answer this question: Why did Congress pass laws after The Jungle? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Justice at Home and Power Abroad$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: The Progressive Movement and Its Reforms$j$, $j${"questions": [{"q": "A muckraker was a:", "options": ["Union leader", "Soldier", "Railroad owner", "Writer who exposed social and business wrongs"]}, {"q": "The Jungle exposed problems in:", "options": ["The meatpacking industry", "Education", "Railroads", "Banking"]}, {"q": "The Sixteenth Amendment allowed:", "options": ["Prohibition", "Women to vote", "Direct election of senators", "A federal income tax"]}, {"q": "Theodore Roosevelt's reform program was called the:", "options": ["New Deal", "Great Society", "Square Deal", "Fair Deal"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: The Progressive Movement and Its Reforms$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,2}'::int[], array[$j$Muckrakers prompted public demand for reform.$j$,$j$It led to the Meat Inspection Act.$j$,$j$It gave Congress power to tax income.$j$,$j$It promised fairness to workers, business and consumers.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: The Progressive Movement and Its Reforms$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Women's Suffrage, Civil Rights Leaders and the NAACP$j$, $j${"questions": [{"q": "The Nineteenth Amendment was ratified in:", "options": ["1865", "1776", "1954", "1920"]}, {"q": "Booker T. Washington founded:", "options": ["Hull House", "Standard Oil", "The NAACP", "Tuskegee Institute"]}, {"q": "W. E. B. Du Bois helped found the:", "options": ["NAACP", "Populist Party", "AFL", "Red Cross"]}, {"q": "Plessy v. Ferguson (1896) allowed:", "options": ["Women to vote", "Income tax", "Separate but equal facilities", "School integration"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Women's Suffrage, Civil Rights Leaders and the NAACP$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,2}'::int[], array[$j$It gave women the right to vote.$j$,$j$He stressed education and trades.$j$,$j$The NAACP was formed in 1909.$j$,$j$It supported segregation until 1954.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Women's Suffrage, Civil Rights Leaders and the NAACP$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Imperialism: The Spanish American War and America as a World Power$j$, $j${"questions": [{"q": "The ship whose explosion helped lead to war with Spain was the:", "options": ["Monitor", "Maine", "Lusitania", "Titanic"]}, {"q": "After the Spanish American War the United States gained:", "options": ["Alaska", "Louisiana", "The Philippines, Guam and Puerto Rico", "Texas"]}, {"q": "The Roosevelt Corollary claimed the right to:", "options": ["End slavery", "Build railroads", "Act as police power in Latin America", "Annex Canada"]}, {"q": "Yellow journalism was:", "options": ["A treaty", "Sensational newspaper reporting", "A tax", "A labor union"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Imperialism: The Spanish American War and America as a World Power$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,1}'::int[], array[$j$The USS Maine exploded in Havana harbor in 1898.$j$,$j$These came through the Treaty of Paris.$j$,$j$It extended the Monroe Doctrine.$j$,$j$Exaggerated stories stirred war fever.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Imperialism: The Spanish American War and America as a World Power$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: World War I and the Home Front$j$, $j${"questions": [{"q": "The Zimmermann Telegram urged:", "options": ["Japan to attack Hawaii", "Britain to surrender", "Mexico to join Germany", "France to leave the war"]}, {"q": "The American commander in Europe was:", "options": ["Douglas MacArthur", "Ulysses Grant", "Dwight Eisenhower", "John Pershing"]}, {"q": "World War I ended with an armistice on:", "options": ["July 4, 1776", "November 11, 1918", "December 7, 1941", "April 9, 1865"]}, {"q": "The Senate refused to join the:", "options": ["League of Nations", "Red Cross", "United Nations", "NATO"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: World War I and the Home Front$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,0}'::int[], array[$j$It helped bring America into the war.$j$,$j$Pershing led the American Expeditionary Forces.$j$,$j$Fighting stopped at the eleventh hour of the eleventh day of the eleventh month.$j$,$j$The Treaty of Versailles was not approved by the Senate.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: World War I and the Home Front$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Reform, Empire and the Great War$j$, $j${"questions": [{"q": "Upton Sinclair wrote:", "options": ["Uncle Tom's Cabin", "The Jungle", "Common Sense", "The Souls of Black Folk"]}, {"q": "The Seventeenth Amendment provided for:", "options": ["Income tax", "Prohibition", "Direct election of senators", "Women's suffrage"]}, {"q": "Which leader wrote The Souls of Black Folk?", "options": ["Booker T. Washington", "Frederick Douglass", "W. E. B. Du Bois", "Marcus Garvey"]}, {"q": "The Seneca Falls Convention was held in:", "options": ["1898", "1848", "1920", "1776"]}, {"q": "The United States gained Alaska by:", "options": ["War with Spain", "Purchase from Russia", "Treaty with Mexico", "Conquest of Canada"]}, {"q": "The Panama Canal was completed in:", "options": ["1929", "1898", "1865", "1914"]}, {"q": "The sinking of the Lusitania occurred in:", "options": ["1865", "1898", "1941", "1915"]}, {"q": "The Nineteenth Amendment gave:", "options": ["Women the right to vote", "Citizenship to all born here", "Freedom to slaves", "The vote to eighteen year olds"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Reform, Empire and the Great War$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,1,1,3,3,0}'::int[], array[$j$His book exposed the meatpacking industry.$j$,$j$Voters, not legislatures, now elect senators.$j$,$j$Du Bois called for full civil rights.$j$,$j$It launched the organized women's rights movement.$j$,$j$Seward's purchase was in 1867.$j$,$j$It shortened sea travel between the oceans.$j$,$j$German submarines killed many Americans aboard.$j$,$j$It was ratified in 1920.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Reform, Empire and the Great War$j$ on conflict (item_id) do nothing;
